<div class="page-heading compact-heading"><div><p class="eyebrow">ATENDIMENTO AO CLIENTE</p><h1>Central de conversas</h1><p class="muted">Converse com seus clientes usando seu número oficial.</p></div><span class="status-pill connected"><i></i> Mensagens via webhook</span></div>
<div class="inbox-layout"><aside class="inbox-list"><div class="inbox-list-head"><b>Conversas</b><span><?=count($data['conversations'])?></span><button title="Filtros">☷</button></div><label class="search-box"><span>⌕</span><input placeholder="Buscar conversa" data-inbox-search></label><div class="inbox-tabs"><button class="selected" type="button" data-inbox-filter="all">Todas</button><button type="button" data-inbox-filter="unread">Não lidas</button><button type="button" data-inbox-filter="assigned">Atribuídas</button></div><div class="conversation-items">
<?php foreach($data['conversations'] as $c): ?><a class="conversation-item <?=$data['selected']==$c['id']?'selected':''?>" data-unread="<?=((int)$c['unread_count']>0)?'1':'0'?>" data-assigned="<?=((int)$c['assignee_id']==(int)$user['id'])?'1':'0'?>" data-search="<?=e($c['contact_name'].' '.$c['phone'].' '.$c['last_message_preview'])?>" href="?r=inbox&id=<?=(int)$c['id']?>"><div class="contact-avatar"><?=e(mb_strtoupper(mb_substr($c['contact_name'],0,1)))?></div><div class="conversation-info"><div class="conversation-title"><b><?=e($c['contact_name']?:$c['phone'])?></b><time><?=e($c['last_message_at']?date('H:i',strtotime($c['last_message_at'])):'')?></time></div><p><?=e($c['last_message_preview']??'Inicie uma conversa')?></p><span class="conversation-label"><?=e($c['status']==='open'?'Aberta':'Fechada')?></span></div></a><?php endforeach; ?><?php if(!$data['conversations']): ?><div class="empty-small">Sua caixa está vazia.<br>Mensagens recebidas aparecem aqui.</div><?php endif; ?></div></aside>
<section class="chat-pane"><?php $selectedConversation=null; foreach($data['conversations'] as $cc) if((int)$cc['id']===$data['selected']) $selectedConversation=$cc; ?><?php if($selectedConversation): ?>
<header class="chat-head"><div class="contact-avatar"><?=e(mb_strtoupper(mb_substr($selectedConversation['contact_name'],0,1)))?></div><div><b><?=e($selectedConversation['contact_name']?:$selectedConversation['phone'])?></b><small>+<?=e($selectedConversation['phone'])?> · WhatsApp</small></div><div class="chat-head-actions"><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign_conversation"><input type="hidden" name="r" value="inbox"><input type="hidden" name="conversation_id" value="<?=(int)$selectedConversation['id']?>"><button title="Atribuir a mim">♙</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close_conversation"><input type="hidden" name="r" value="inbox"><input type="hidden" name="conversation_id" value="<?=(int)$selectedConversation['id']?>"><button title="Encerrar conversa">✓</button></form></div></header>
<?php $windowOpen=!empty($selectedConversation['last_inbound_at'])&&strtotime($selectedConversation['last_inbound_at'])>=time()-86400; ?><div class="window-alert <?=$windowOpen?'window-open':''?>"><?=$windowOpen?'● Janela de atendimento aberta · respostas livres permitidas por até 24 horas após a última mensagem do cliente.':'◷ Fora da janela de 24 horas · inicie com um template aprovado.'?></div>
<div class="message-stream" id="message-stream" tabindex="0"><?php foreach($data['messages'] as $msg): ?><div class="message-row <?=$msg['direction']==='out'?'outgoing':'incoming'?>" data-message-id="<?=(int)$msg['id']?>"><div class="bubble"><?php if(!empty($msg['media_id'])): $mediaUrl='?r=media&id='.(int)$msg['id']; if(str_starts_with((string)$msg['media_mime'],'image/')): ?><a class="message-media" href="<?=$mediaUrl?>" target="_blank" rel="noopener"><img src="<?=$mediaUrl?>" alt="<?=e($msg['media_filename']?:'Imagem recebida')?>" loading="lazy"></a><?php elseif(str_starts_with((string)$msg['media_mime'],'audio/')): ?><audio class="message-audio" controls preload="none" src="<?=$mediaUrl?>">Seu navegador não reproduz este áudio.</audio><?php elseif(str_starts_with((string)$msg['media_mime'],'video/')): ?><video class="message-video" controls preload="none" src="<?=$mediaUrl?>">Seu navegador não reproduz este vídeo.</video><?php else: ?><a class="message-file" href="<?=$mediaUrl?>">⇩ <?=e($msg['media_filename']?:'Baixar anexo')?></a><?php endif; ?><?php endif; ?><?php $messageText=(string)($msg['body']??''); if($messageText&&!str_starts_with($messageText,'Anexo recebido:')): ?><div><?=nl2br(e($messageText))?></div><?php endif; ?><small><?=e(date('H:i',strtotime($msg['created_at'])))?> · <?=e($msg['status'])?></small></div></div><?php endforeach; ?><?php if(!$data['messages']): ?><div class="chat-empty"><div>✳</div><b>Conversa iniciada</b><p>As mensagens recebidas e enviadas aparecem nesta área.</p></div><?php endif; ?></div><button class="jump-to-latest" type="button" title="Ir para a mensagem mais recente" aria-label="Ir para a mensagem mais recente" hidden>↓</button>
<?php if($windowOpen): ?><form method="post" class="composer" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="send_message"><input type="hidden" name="r" value="inbox"><input type="hidden" name="conversation_id" value="<?=(int)$selectedConversation['id']?>"><div class="composer-tools"><label class="attachment-button" for="attachment" title="Anexar imagem, vídeo, áudio ou PDF">＋</label><input type="file" id="attachment" name="attachment" class="visually-hidden" accept="image/jpeg,image/png,video/mp4,audio/aac,audio/amr,audio/mpeg,audio/mp4,audio/ogg,application/pdf" data-attachment-input><button type="button" title="Emoji" data-emoji>☺</button></div><textarea name="body" rows="1" placeholder="Digite uma mensagem ou escolha um anexo..."></textarea><span class="attachment-name" data-attachment-name></span><?php if(!empty($data['quick_replies'])): ?><select class="quick-reply-select" title="Inserir resposta rápida" data-quick-replies><option value="" selected>Resposta rápida</option><?php foreach($data['quick_replies'] as $reply): ?><option data-body="<?=e($reply['body'])?>"><?=e($reply['name'])?></option><?php endforeach; ?></select><?php endif; ?><button class="send-button" title="Enviar">➤</button></form><small class="composer-hint">Imagens até 5 MB; vídeos, áudios e PDFs até 16 MB.</small>
<?php else: ?><form method="post" class="template-composer"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="send_template"><input type="hidden" name="r" value="inbox"><input type="hidden" name="conversation_id" value="<?=(int)$selectedConversation['id']?>"><span>Iniciar com template</span><select name="template_id" required <?=empty($data['approved_templates'])||$selectedConversation['consent_status']!=='opted_in'?'disabled':''?>><option value="">Selecione template aprovado</option><?php foreach($data['approved_templates'] as $t): ?><option value="<?=(int)$t['id']?>"><?=e($t['name'])?> · <?=e($t['language'])?></option><?php endforeach; ?></select><textarea name="template_params" rows="2" placeholder="Parâmetros do template, um por linha; deixe vazio se não houver variáveis"></textarea><button class="button primary" type="submit" <?=empty($data['approved_templates'])||$selectedConversation['consent_status']!=='opted_in'?'disabled':''?>>Enviar template</button><?php if($selectedConversation['consent_status']!=='opted_in'): ?><small>Registre o consentimento do contato antes de iniciar.</small><?php elseif(empty($data['approved_templates'])): ?><small>Nenhum template aprovado disponível.</small><?php else: ?><small>Informe os parâmetros do corpo, um valor por linha, quando o template tiver variáveis.</small><?php endif; ?></form><?php endif; ?>
<?php else: ?><div class="chat-empty full"><div class="empty-art">◌</div><b>Selecione uma conversa</b><p>Escolha uma conversa ao lado para ver as mensagens.</p></div><?php endif; ?></section></div>
